// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: The human edits an open draft while an agent keeps working on it (fake transport, fake timers): per-part
//          saves merged by the server, live polling that keeps unsaved edits, the conflict prompt naming the part,
//          polling paused while the page is hidden, and export naming / simulation inputs written to the project.

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { updatedByAgent } from './drafts'
import { defaultProjectData, type ProjectData } from './project'
import { createProjectSession, DRAFT_POLL_MS } from './projectSession'
import { createFakeTransport } from './projectTransport.fake'
import type { ProjectRecord } from '#/server/projects.server'

const project = (): ProjectRecord => ({
  id: 'p1',
  name: 'Výrazy',
  data: {
    ...defaultProjectData(),
    def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
    ll: { grammar: 'E -> id', input: 'id + id' },
    prec: { terminals: ['+', 'id'], cells: {}, rules: 'E -> id', input: 'id' },
    names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
  },
  revision: 3,
  createdAt: '2026-01-01T00:00:00.000Z',
  updatedAt: '2026-01-01T00:00:00.000Z',
  view: { llSim: { step: 0, speed: 1 } },
})

const AGENT_GRAMMAR = 'E -> id R\nR -> + E\nR -> eps'
const setRelation = (d: ProjectData): ProjectData => ({ ...d, prec: { ...d.prec, cells: { 'id\u0001+': '>' } } })
const setGrammar = (grammar: string) => (d: ProjectData): ProjectData => ({ ...d, ll: { ...d.ll, grammar } })

// An agent forks a draft; the human opens it in the editor (mounted: resume()).
async function openDraft() {
  const fake = createFakeTransport(project())
  const draft = fake.createDraft('Oprava konfliktu')
  const session = createProjectSession((await fake.transport.loadDraft({ draftId: draft.id }))!, fake.transport)
  session.resume()
  await vi.advanceTimersByTimeAsync(0)
  return { fake, draft, session, state: () => session.getState(), server: () => fake.draft(draft.id)! }
}

beforeEach(() => vi.useFakeTimers())
afterEach(() => vi.useRealTimers())

describe('the human edits a draft while an agent works on it', () => {
  it('the agent edits the grammar rules while the human edits the precedence table: both survive, no prompt', async () => {
    const { fake, draft, session, state, server } = await openDraft()

    session.edit(setRelation)
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR }) // before the human's save goes out
    await vi.advanceTimersByTimeAsync(600)

    // Only the touched part was sent, based on the revision the human had.
    expect(fake.callsOf('saveDraft').map((c) => c.input)).toEqual([
      { draftId: draft.id, parts: { precTable: { terminals: ['+', 'id'], cells: { 'id\u0001+': '>' } } }, baseRevision: 1 },
    ])
    expect(server().parts).toMatchObject({ grammarRules: AGENT_GRAMMAR, precTable: { cells: { 'id\u0001+': '>' } } })
    // The client took the merged state.
    expect(state()).toMatchObject({ status: 'saved', unsaved: false, conflict: null, conflictParts: [] })
    expect(state().data.ll.grammar).toBe(AGENT_GRAMMAR)
    expect(state().data.prec.cells).toEqual({ 'id\u0001+': '>' })
    expect(state().draft?.revision).toBe(3)
  })

  it('the next save is based on the merged revision (no self-conflict)', async () => {
    const { fake, draft, session, state, server } = await openDraft()
    session.edit(setRelation)
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    await vi.advanceTimersByTimeAsync(600)

    session.edit(setGrammar('E -> id'))
    await vi.advanceTimersByTimeAsync(600)

    expect(fake.callsOf('saveDraft').at(-1)?.input).toMatchObject({ parts: { grammarRules: 'E -> id' }, baseRevision: 3 })
    expect(state().status).toBe('saved')
    expect(server()).toMatchObject({ revision: 4, parts: { grammarRules: 'E -> id' } })
  })

  it('the same part edited on both sides gives the conflict prompt naming the part', async () => {
    const { fake, draft, session, state, server } = await openDraft()

    session.edit(setGrammar('E -> id + E'))
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    await vi.advanceTimersByTimeAsync(600)

    expect(state()).toMatchObject({ status: 'conflict', conflictParts: ['grammarRules'], unsaved: true })
    expect(state().data.ll.grammar).toBe('E -> id + E') // the human's text stays on screen
    expect(server().parts.grammarRules).toBe(AGENT_GRAMMAR)
    // Nothing is saved while the prompt is open.
    await vi.advanceTimersByTimeAsync(10_000)
    expect(fake.callsOf('saveDraft')).toHaveLength(1)
  })

  it('"mine" overwrites the part with the human’s version; other agent changes are kept', async () => {
    const { fake, draft, session, state, server } = await openDraft()
    session.edit(setGrammar('E -> id + E'))
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR, reductionRules: 'E -> E + E' })
    await vi.advanceTimersByTimeAsync(600)

    await session.resolveConflict('mine')

    expect(server().parts).toMatchObject({ grammarRules: 'E -> id + E', reductionRules: 'E -> E + E' })
    expect(state()).toMatchObject({ status: 'saved', conflict: null, conflictParts: [] })
    expect(state().data.prec.rules).toBe('E -> E + E')
  })

  it('"theirs" takes the agent’s version of the part and still saves the human’s other edits', async () => {
    const { fake, draft, session, state, server } = await openDraft()
    session.edit(setGrammar('E -> id + E'))
    session.edit(setRelation)
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    await vi.advanceTimersByTimeAsync(600)
    expect(state().conflictParts).toEqual(['grammarRules'])

    await session.resolveConflict('theirs')
    await vi.advanceTimersByTimeAsync(600)

    expect(state().data.ll.grammar).toBe(AGENT_GRAMMAR)
    expect(server().parts).toMatchObject({ grammarRules: AGENT_GRAMMAR, precTable: { cells: { 'id\u0001+': '>' } } })
    expect(state()).toMatchObject({ status: 'saved', unsaved: false, conflict: null })
  })

  it('human saves are human changes: the draft is not "updated by agent" afterwards', async () => {
    const { fake, draft, session, server } = await openDraft()
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    session.edit(setRelation)
    await vi.advanceTimersByTimeAsync(600)
    expect(server().lastChangedBy).toBe('human')
    expect(updatedByAgent(server())).toBe(false)
  })
})

describe('an open draft refreshes live', () => {
  it('an agent’s change appears after a poll, and unsaved edits in other parts are kept', async () => {
    const { fake, draft, session, state } = await openDraft()
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS - 100)
    session.edit(setRelation) // not saved yet when the poll comes
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })

    await vi.advanceTimersByTimeAsync(100)
    expect(state().data.ll.grammar).toBe(AGENT_GRAMMAR)
    expect(state().data.prec.cells).toEqual({ 'id\u0001+': '>' })
    expect(state()).toMatchObject({ status: 'pending', unsaved: true, draft: { revision: 2 } })

    await vi.advanceTimersByTimeAsync(600)
    expect(fake.draft(draft.id)?.parts).toMatchObject({ grammarRules: AGENT_GRAMMAR, precTable: { cells: { 'id\u0001+': '>' } } })
    expect(state().status).toBe('saved')
  })

  it('a refresh that brings the agent’s change is recorded as viewed', async () => {
    const { fake, draft, server } = await openDraft()
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    expect(updatedByAgent(server())).toBe(true)
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS)
    expect(server().humanViewedRevision).toBe(2)
  })

  it('an unsaved edit of a part the agent changed too gives the conflict prompt on refresh', async () => {
    const { fake, draft, session, state } = await openDraft()
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS - 100)
    session.edit(setGrammar('E -> id + E'))
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    await vi.advanceTimersByTimeAsync(100)
    expect(state()).toMatchObject({ status: 'conflict', conflictParts: ['grammarRules'] })
    expect(state().data.ll.grammar).toBe('E -> id + E')
  })

  it('polling stops while the page is hidden and resumes at once when it is shown', async () => {
    const { fake, draft, session, state } = await openDraft()
    const polls = () => fake.callsOf('loadDraft').length
    const before = polls()
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS * 2)
    expect(polls()).toBe(before + 2)

    session.pageHidden()
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS * 10)
    expect(polls()).toBe(before + 2)

    session.pageShown()
    await vi.advanceTimersByTimeAsync(0)
    expect(polls()).toBe(before + 3)
    expect(state().data.ll.grammar).toBe(AGENT_GRAMMAR)
  })

  it('polling stops when the editor goes away', async () => {
    const { fake, session } = await openDraft()
    session.dispose()
    const before = fake.callsOf('loadDraft').length
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS * 5)
    expect(fake.callsOf('loadDraft')).toHaveLength(before)
  })

  it('a draft the agent discarded becomes read-only', async () => {
    const { fake, draft, session, state } = await openDraft()
    fake.discardDraft(draft.id)
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS)
    expect(state()).toMatchObject({ readOnly: true, draft: { state: 'discarded' } })
    session.edit(setRelation)
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.callsOf('saveDraft')).toHaveLength(0)
  })

  it('a project session does not poll', async () => {
    const fake = createFakeTransport(project())
    createProjectSession(project(), fake.transport).resume()
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS * 3)
    expect(fake.calls).toHaveLength(0)
  })
})

describe('export naming and simulation inputs in a draft view', () => {
  it("are saved to the project: the project's revision moves, the draft's does not", async () => {
    const { fake, session, state, server } = await openDraft()

    session.edit((d) => ({ ...d, names: { ...d.names, ntPrefix: 'NT_' }, ll: { ...d.ll, input: 'id' } }))
    await vi.advanceTimersByTimeAsync(600)

    expect(fake.callsOf('saveDraft')).toHaveLength(0)
    expect(fake.server.record).toMatchObject({ revision: 4, data: { names: { ntPrefix: 'NT_' }, ll: { grammar: 'E -> id', input: 'id' } } })
    expect(server().revision).toBe(1)
    expect(state()).toMatchObject({ status: 'saved', unsaved: false })
  })

  it('are never stored in the draft, even when saved together with a part', async () => {
    const { fake, session, server } = await openDraft()
    session.edit((d) => setRelation({ ...d, prec: { ...d.prec, input: 'id + id' } }))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.server.record?.data.prec).toMatchObject({ input: 'id + id', cells: {} })
    expect(server().parts.precTable.cells).toEqual({ 'id\u0001+': '>' })
    expect(fake.callsOf('saveDraft')[0]?.input).not.toHaveProperty('parts.input')
  })
})

describe('history operations of a draft', () => {
  it("a named version first saves the human's unsaved edits into the draft", async () => {
    const { fake, session, server } = await openDraft()
    session.edit(setRelation)

    await session.saveNamedVersion('Pred úpravou')

    expect(fake.callsOf('saveDraft')).toHaveLength(1)
    expect(server().parts.precTable.cells).toEqual({ 'id\u0001+': '>' })
    expect(fake.callsOf('createDraftSnapshot')).toHaveLength(1)
  })

  it('a restored draft is the base of the next per-part save (no self-conflict)', async () => {
    const { fake, draft, session, state, server } = await openDraft()
    const snapshot = await session.saveNamedVersion('Začiatok')
    fake.agentEdit(draft.id, { grammarRules: AGENT_GRAMMAR })
    await session.restoreVersion(snapshot.id)

    session.edit(setGrammar('E -> id + E'))
    await vi.advanceTimersByTimeAsync(600)

    expect(state()).toMatchObject({ status: 'saved', conflictParts: [] })
    expect(server().parts.grammarRules).toBe('E -> id + E')
  })
})

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes view for the grids"
// Changes: A draft session follows its project's current content (the old side of the Changes view and the adopt
//          dialog), so a project change made elsewhere shows up without a reload.
describe("the draft's project follows the server", () => {
  it('a draft session starts with its project, a project session has none', async () => {
    const { state } = await openDraft()
    expect(state().project).toMatchObject({ id: 'p1', revision: 3, data: { ll: { grammar: 'E -> id' } } })
    const fake = createFakeTransport(project())
    expect(createProjectSession(project(), fake.transport).getState().project).toBeNull()
  })

  it('a project change made elsewhere reaches the session on the next refresh', async () => {
    const { fake, state } = await openDraft()
    fake.externalSave(setGrammar('E -> id + id')(project().data))
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS)
    expect(state().project).toMatchObject({ revision: 4, data: { ll: { grammar: 'E -> id + id' } } })
    // The draft itself is untouched.
    expect(state().data.ll.grammar).toBe('E -> id')
  })

  it('a refresh without a project change keeps the same project (nothing to recompute)', async () => {
    const { state } = await openDraft()
    const before = state().project
    await vi.advanceTimersByTimeAsync(DRAFT_POLL_MS * 2)
    expect(state().project).toBe(before)
  })
})
